                                                                                                                                                                                                                   
  CREATE TABLE "STS_FOLDER_CLASS"                                                                                                                                                                        
   (	"FOLDER_CLASS_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"FOLDER_CLASS_NAME" VARCHAR2(45),                                                                                                                                                                                 
	"FOLDER_CLASS_LEVEL" VARCHAR2(255) DEFAULT 1,                                                                                                                                                                     
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                                 
	"TENANT_ID" NUMBER(10,0),                                                                                                                                                                                         
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                        
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                             
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                        
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                               
	"SCOPE_TYPE" NVARCHAR2(20) DEFAULT 'ALL',                                                                                                                                                                         
	"SORT" NUMBER(20,0) DEFAULT 1,                                                                                                                                                                                    
	 PRIMARY KEY ("FOLDER_CLASS_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                              
   ) ;                                                                                                                                                                                                             

